jsonb_build_array(jsonb_build_object('title','1. Observar a fonte','instruction','Observe personagem, imagem, objeto ou relato fictício e identifique pistas.','activity','Marque o que a fonte mostra e uma coisa que ela não permite saber.','support','Vocabulário visual, leitura pelo adulto e exemplo resolvido.'),jsonb_build_object('title','2. Ordenar e comparar','instruction','Organize cenas em antes, agora e depois; compare mudança e permanência.','activity','Monte linha do tempo de cartões ou tabela de duas colunas sobre '||lower(title)||'.','support','Modelo pronto, pistas graduadas e Prática guiada antes da independente.'),jsonb_build_object('title','3. Contar com evidência','instruction','Conte o que mudou ou permaneceu e aponte a pista usada.','activity','Escolha fala, sequência, desenho, cartões ou escrita para apresentar a conclusão.','support','Resposta oral, apontada, desenhada, digitada, escrita ou assistida.')),
