jsonb_build_array(jsonb_build_object('title','Guia de análise histórica — '||code,'purpose',goal,'sections',jsonb_build_array(
 jsonb_build_object('heading','Contextualize o tempo presente','content',jsonb_build_array('Diferencie democracia, autoritarismo, totalitarismo, golpe, revolução, genocídio, colonialismo e terrorismo sem banalizar ou igualar fenômenos distintos.','Guerras, genocídios, ditaduras, perseguições e violações de direitos devem ser tratados de modo informativo, não gráfico e adequado à idade; não exiba imagens chocantes nem proponha encenação de violência, opressão ou sofrimento.','Inclua protagonismo negro, indígena, quilombola, feminino, juvenil, trabalhador, migrante e de pessoas com deficiência sem reduzir grupos a vítimas.')),
 jsonb_build_object('heading','Verificar fontes, memória e desinformação','content',jsonb_build_array('Compare autoria, data, contexto, finalidade, linguagem, evidências, silêncios e limites de documentos, imprensa, propaganda, estatísticas, testemunhos publicados e mídias digitais.','Diferencie fato documentado, interpretação historiográfica, memória, opinião, propaganda e desinformação; verifique afirmações controversas em fontes institucionais e pesquisas reconhecidas.','Analise causas múltiplas, escalas local e global, continuidades, rupturas, responsabilidades institucionais e resistências, sem falsa equivalência entre evidência e negação.')),
 jsonb_build_object('heading','Rotina adaptativa','content',jsonb_build_array('Divida fontes e textos em etapas, dê uma instrução por vez, permita pausa planejada e sinalize retomada.','Aceite resposta oral, apontada, mapeada, diagramada, gravada, digitada, escrita ou com tecnologia assistiva.','Não solicite posição partidária, experiência de violência, discriminação, migração, religião, raça ou identidade pessoal do estudante.')),
 jsonb_build_object('heading','Critério','content','Analisa quatro de cinco processos usando contexto, cronologia, causalidade, conceito, fonte verificada, perspectiva e limite interpretativo.')))),
jsonb_build_array(jsonb_build_object('title','1. Situar e verificar fontes','instruction','Identifique período, escala, grupos, autoria, finalidade, linguagem, evidências, silêncios e limites.','activity','Compare fontes e classifique fato documentado, interpretação, memória, propaganda ou opinião.','support','Glossário, linha do tempo, mapa, fonte ampliada e exemplo resolvido.'),jsonb_build_object('title','2. Explicar processos e disputas','instruction','Relacione causas, estruturas, decisões, resistências, mudanças, permanências e consequências.','activity','Monte matriz causal, mapa de fluxos ou cronologia de '||lower(title)||'.','support','Prática guiada antes da independente e redução gradual de pistas.'),jsonb_build_object('title','3. Argumentar e revisar','instruction','Formule argumento com evidências verificadas, reconheça agência, outra interpretação e limites sem falsa equivalência.','activity','Cite fontes, confronte contraexemplo e revise a conclusão.','support','Resposta oral, apontada, mapeada, diagramada, gravada, digitada, escrita ou assistida.')),
